// Add or update a player's score
async function addScore(playerId, points) {
  await redis.zIncrBy('leaderboard:global', points, playerId);
}

// Get top N players
async function getTopPlayers(n) {
  // ZRANGE with REV returns highest scores first
  const result = await redis.zRangeWithScores('leaderboard:global', 0, n - 1, { REV: true });
  return result.map((entry, i) => ({
    rank: i + 1,
    playerId: entry.value,
    score: entry.score,
  }));
}

// Get a player's rank and score
async function getPlayerStats(playerId) {
  const [rank, score] = await Promise.all([
    redis.zRevRank('leaderboard:global', playerId),  // 0-indexed from top
    redis.zScore('leaderboard:global', playerId),
  ]);
  return { rank: rank + 1, score };
}

// Get players around a rank
async function getNeighbours(playerId, range = 5) {
  const rank = await redis.zRevRank('leaderboard:global', playerId);
  const start = Math.max(0, rank - range);
  const end = rank + range;
  return redis.zRangeWithScores('leaderboard:global', start, end, { REV: true });
}

async function isRateLimited(userId, limit = 100, windowMs = 60000) {
  const now = Date.now();
  const windowStart = now - windowMs;
  const key = `rate:${userId}`;

  const pipeline = redis.pipeline();
  // 1. Remove requests outside the window
  pipeline.zRemRangeByScore(key, 0, windowStart);
  // 2. Add current request
  pipeline.zAdd(key, { score: now, value: `${now}-${Math.random()}` });
  // 3. Count requests in window
  pipeline.zCard(key);
  // 4. Reset TTL
  pipeline.expire(key, Math.ceil(windowMs / 1000));

  const results = await pipeline.exec();
  const requestCount = results[2][1];  // zCard result

  return requestCount > limit;
}

// Priority queue: lower score = higher priority
async function enqueue(task, priority) {
  await redis.zAdd('tasks:priority', { score: priority, value: JSON.stringify(task) });
}

// Dequeue highest priority task (lowest score)
async function dequeue() {
  const result = await redis.zPopMin('tasks:priority');
  return result ? JSON.parse(result.value) : null;
}

// Blocking dequeue
async function dequeueBlocking(timeout = 30) {
  const result = await redis.bzPopMin('tasks:priority', timeout);
  return result ? JSON.parse(result.value) : null;
}
